// Drizzle schema for Refrain. Drizzle Kit generates versioned SQL migrations
// from this file into src/db/migrations (see docs/development.md).
//
// The model implements ADR 0002 and is described in docs/data-model.md, which
// also lists the rules that constraints alone cannot enforce.
//
// Conventions (ADR 0003):
// - Table and column names are snake_case and written out explicitly.
// - Enumerations are `text` columns with CHECK constraints, not native enums.
// - Primary keys are `uuid` values generated by PostgreSQL (gen_random_uuid).
// - Timestamps are `timestamptz`, set from the database clock (now()).
// - Constraints are named, so a violation names the rule that was broken.
// - Catalog tables never cascade into authored tables: every foreign key from
//   writing to the catalog is ON DELETE RESTRICT.
//
// One constraint is not expressible in Drizzle and lives in a custom
// migration: the deferrable UNIQUE (memory_id, position) on memory_music.
import { sql } from "drizzle-orm";
import {
  boolean,
  check,
  date,
  foreignKey,
  index,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  smallint,
  text,
  timestamp,
  unique,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

// ---------------------------------------------------------------------------
// Shared values
// ---------------------------------------------------------------------------

/** Kinds of authored entry. */
export const entryKinds = [
  "album_journal",
  "artist_journal",
  "memory",
] as const;
export type EntryKind = (typeof entryKinds)[number];

/** Languages writing can be in (also the interface languages). */
export const locales = ["en", "pt-BR"] as const;
export type Locale = (typeof locales)[number];

/** Visibility of one language version (ADR 0002, D4.1). */
export const visibilityStatuses = ["draft", "private", "published"] as const;
export type VisibilityStatus = (typeof visibilityStatuses)[number];

export const artistKinds = ["person", "group"] as const;

const createdAt = () =>
  timestamp("created_at", { withTimezone: true }).notNull().defaultNow();

const updatedAt = () =>
  timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdateFn(() => sql`now()`);

const archivedAt = () => timestamp("archived_at", { withTimezone: true });

// A rich-text document: Tiptap (ProseMirror) JSON, `null` while nothing has
// been written. The node and mark schema is validated at the server boundary;
// the database checks only the outer shape. `body_text` is the plain-text
// projection used for search and word counts (ADR 0002, D6).
const richText = () => ({
  body: jsonb("body"),
  bodyFormatVersion: smallint("body_format_version").notNull().default(1),
  bodyText: text("body_text").notNull().default(""),
});

const richTextChecks = (table: string) => [
  check(
    `${table}_body_is_document_check`,
    sql`body is null or (jsonb_typeof(body) = 'object' and body ->> 'type' = 'doc')`,
  ),
  check(
    `${table}_body_text_requires_body_check`,
    sql`body is not null or body_text = ''`,
  ),
  check(`${table}_body_format_version_check`, sql`body_format_version >= 1`),
];

// Ratings are integer half steps: 1 = 0.5 stars ... 10 = 5 stars. NULL means
// "No rating", which is distinct from the lowest rating.
const ratingCheck = (table: string) =>
  check(
    `${table}_rating_half_steps_check`,
    sql`rating_half_steps between 1 and 10`,
  );

const localeCheck = (table: string) =>
  check(`${table}_locale_check`, sql`locale in ('en', 'pt-BR')`);

// ---------------------------------------------------------------------------
// Music catalog: factual, replaceable metadata. Cascades stay inside it.
// ---------------------------------------------------------------------------

export const artists = pgTable(
  "artists",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    name: text("name").notNull(),
    sortName: text("sort_name"),
    kind: text("kind", { enum: artistKinds }).notNull(),
    mbArtistId: uuid("mb_artist_id"),
    photoUrl: text("photo_url"),
    photoCredit: text("photo_credit"),
    photoLicense: text("photo_license"),
    photoSourceUrl: text("photo_source_url"),
    archivedAt: archivedAt(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    unique("artists_mb_artist_id_unique").on(t.mbArtistId),
    check("artists_name_check", sql`btrim(name) <> ''`),
    check("artists_kind_check", sql`kind in ('person', 'group')`),
    check(
      "artists_photo_attribution_check",
      sql`photo_url is null or (photo_credit is not null and photo_license is not null)`,
    ),
  ],
);

export const albums = pgTable(
  "albums",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    title: text("title").notNull(),
    firstReleaseYear: smallint("first_release_year"),
    mbReleaseGroupId: uuid("mb_release_group_id"),
    coverUrl: text("cover_url"),
    coverSource: text("cover_source"),
    archivedAt: archivedAt(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    unique("albums_mb_release_group_id_unique").on(t.mbReleaseGroupId),
    check("albums_title_check", sql`btrim(title) <> ''`),
    check(
      "albums_first_release_year_check",
      sql`first_release_year between 1800 and 2100`,
    ),
    check(
      "albums_cover_source_check",
      sql`cover_url is null or cover_source is not null`,
    ),
  ],
);

export const albumArtists = pgTable(
  "album_artists",
  {
    albumId: uuid("album_id").notNull(),
    artistId: uuid("artist_id").notNull(),
    position: smallint("position").notNull(),
    creditedAs: text("credited_as"),
  },
  (t) => [
    primaryKey({
      name: "album_artists_pkey",
      columns: [t.albumId, t.artistId],
    }),
    foreignKey({
      name: "album_artists_album_fk",
      columns: [t.albumId],
      foreignColumns: [albums.id],
    }).onDelete("cascade"),
    foreignKey({
      name: "album_artists_artist_fk",
      columns: [t.artistId],
      foreignColumns: [artists.id],
    }).onDelete("restrict"),
    unique("album_artists_position_unique").on(t.albumId, t.position),
    check("album_artists_position_check", sql`position >= 1`),
    index("album_artists_artist_id_idx").on(t.artistId),
  ],
);

// A specific release of an album. In v1 each album has exactly one, its
// reference edition, which defines track order (ADR 0002, D2).
export const albumEditions = pgTable(
  "album_editions",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    albumId: uuid("album_id").notNull(),
    label: text("label"),
    releaseDate: date("release_date", { mode: "string" }),
    country: text("country"),
    mbReleaseId: uuid("mb_release_id"),
    isReference: boolean("is_reference").notNull().default(false),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    foreignKey({
      name: "album_editions_album_fk",
      columns: [t.albumId],
      foreignColumns: [albums.id],
    }).onDelete("cascade"),
    unique("album_editions_mb_release_id_unique").on(t.mbReleaseId),
    // Target of edition_tracks' composite key, which keeps an edition's
    // tracks on the edition's own album.
    unique("album_editions_id_album_unique").on(t.id, t.albumId),
    uniqueIndex("album_editions_one_reference_idx")
      .on(t.albumId)
      .where(sql`is_reference`),
    check("album_editions_country_check", sql`country ~ '^[A-Z]{2}$'`),
    index("album_editions_album_id_idx").on(t.albumId),
  ],
);

// A recording. It exists independently of albums, so a single can be linked
// from a memory, and the same recording can belong to several albums.
export const tracks = pgTable(
  "tracks",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    title: text("title").notNull(),
    lengthMs: integer("length_ms"),
    credit: text("credit"),
    mbRecordingId: uuid("mb_recording_id"),
    archivedAt: archivedAt(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    unique("tracks_mb_recording_id_unique").on(t.mbRecordingId),
    check("tracks_title_check", sql`btrim(title) <> ''`),
    check("tracks_length_ms_check", sql`length_ms > 0`),
  ],
);

export const trackArtists = pgTable(
  "track_artists",
  {
    trackId: uuid("track_id").notNull(),
    artistId: uuid("artist_id").notNull(),
    position: smallint("position").notNull(),
  },
  (t) => [
    primaryKey({
      name: "track_artists_pkey",
      columns: [t.trackId, t.artistId],
    }),
    foreignKey({
      name: "track_artists_track_fk",
      columns: [t.trackId],
      foreignColumns: [tracks.id],
    }).onDelete("cascade"),
    foreignKey({
      name: "track_artists_artist_fk",
      columns: [t.artistId],
      foreignColumns: [artists.id],
    }).onDelete("restrict"),
    unique("track_artists_position_unique").on(t.trackId, t.position),
    check("track_artists_position_check", sql`position >= 1`),
    index("track_artists_artist_id_idx").on(t.artistId),
  ],
);

// Membership: the recording belongs to the album, independently of any
// edition. Track reflections reference this table (ADR 0002, D2.3).
export const albumTracks = pgTable(
  "album_tracks",
  {
    albumId: uuid("album_id").notNull(),
    trackId: uuid("track_id").notNull(),
  },
  (t) => [
    primaryKey({
      name: "album_tracks_pkey",
      columns: [t.albumId, t.trackId],
    }),
    foreignKey({
      name: "album_tracks_album_fk",
      columns: [t.albumId],
      foreignColumns: [albums.id],
    }).onDelete("cascade"),
    foreignKey({
      name: "album_tracks_track_fk",
      columns: [t.trackId],
      foreignColumns: [tracks.id],
    }).onDelete("restrict"),
    index("album_tracks_track_id_idx").on(t.trackId),
  ],
);

// Order and disc layout of an album's recordings within one edition.
export const editionTracks = pgTable(
  "edition_tracks",
  {
    editionId: uuid("edition_id").notNull(),
    albumId: uuid("album_id").notNull(),
    trackId: uuid("track_id").notNull(),
    discNumber: smallint("disc_number").notNull().default(1),
    position: smallint("position").notNull(),
  },
  (t) => [
    primaryKey({
      name: "edition_tracks_pkey",
      columns: [t.editionId, t.trackId],
    }),
    foreignKey({
      name: "edition_tracks_edition_fk",
      columns: [t.editionId, t.albumId],
      foreignColumns: [albumEditions.id, albumEditions.albumId],
    }).onDelete("cascade"),
    foreignKey({
      name: "edition_tracks_album_track_fk",
      columns: [t.albumId, t.trackId],
      foreignColumns: [albumTracks.albumId, albumTracks.trackId],
    }).onDelete("cascade"),
    unique("edition_tracks_position_unique").on(
      t.editionId,
      t.discNumber,
      t.position,
    ),
    check("edition_tracks_disc_number_check", sql`disc_number >= 1`),
    check("edition_tracks_position_check", sql`position >= 1`),
    index("edition_tracks_album_track_idx").on(t.albumId, t.trackId),
  ],
);

// ---------------------------------------------------------------------------
// Authored content: personal, irreplaceable writing.
// ---------------------------------------------------------------------------

// The supertype of every entry. It has no visibility column: visibility
// belongs to each language version (entry_texts.status).
export const entries = pgTable(
  "entries",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    kind: text("kind", { enum: entryKinds }).notNull(),
    // Moves the entry to Recently deleted. Not a visibility state (D4.2).
    deletedAt: timestamp("deleted_at", { withTimezone: true }),
    // Set once, when any language version is first published. It freezes the
    // slug (D7.4) and is never cleared by unpublishing.
    firstPublishedAt: timestamp("first_published_at", { withTimezone: true }),
    // Optimistic concurrency for saves.
    version: integer("version").notNull().default(1),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    // Target of the subtype and slug composite keys, which pin each row to an
    // entry of the right kind.
    unique("entries_id_kind_unique").on(t.id, t.kind),
    check(
      "entries_kind_check",
      sql`kind in ('album_journal', 'artist_journal', 'memory')`,
    ),
    check("entries_version_check", sql`version >= 1`),
  ],
);

// One language version of an entry, with its own visibility (D3.2, D4.1).
export const entryTexts = pgTable(
  "entry_texts",
  {
    entryId: uuid("entry_id").notNull(),
    locale: text("locale", { enum: locales }).notNull(),
    // The language the entry was written in. A translation (false) is always
    // written by the author, never generated (D3.1).
    isOriginal: boolean("is_original").notNull(),
    status: text("status", { enum: visibilityStatuses })
      .notNull()
      .default("draft"),
    publishedAt: timestamp("published_at", { withTimezone: true }),
    // Memory title. Journals take their title from the catalog.
    title: text("title"),
    // Opening sentence (journals).
    opening: text("opening"),
    ...richText(),
    // Optional margin note (album journals).
    marginNote: text("margin_note"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    primaryKey({
      name: "entry_texts_pkey",
      columns: [t.entryId, t.locale],
    }),
    foreignKey({
      name: "entry_texts_entry_fk",
      columns: [t.entryId],
      foreignColumns: [entries.id],
    }).onDelete("cascade"),
    uniqueIndex("entry_texts_one_original_idx")
      .on(t.entryId)
      .where(sql`is_original`),
    localeCheck("entry_texts"),
    check(
      "entry_texts_status_check",
      sql`status in ('draft', 'private', 'published')`,
    ),
    check(
      "entry_texts_published_at_check",
      sql`(status = 'published') = (published_at is not null)`,
    ),
    check("entry_texts_title_check", sql`title is null or btrim(title) <> ''`),
    ...richTextChecks("entry_texts"),
  ],
);

export const albumJournals = pgTable(
  "album_journals",
  {
    entryId: uuid("entry_id").primaryKey(),
    kind: text("kind", { enum: ["album_journal"] })
      .notNull()
      .default("album_journal"),
    albumId: uuid("album_id").notNull(),
    // At most one featured journal per album (D1.2, INV-1). Featuring never
    // changes visibility.
    isFeatured: boolean("is_featured").notNull().default(false),
    // Album rating, independent of every track rating (D5.3).
    ratingHalfSteps: smallint("rating_half_steps"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    foreignKey({
      name: "album_journals_entry_fk",
      columns: [t.entryId, t.kind],
      foreignColumns: [entries.id, entries.kind],
    }).onDelete("cascade"),
    foreignKey({
      name: "album_journals_album_fk",
      columns: [t.albumId],
      foreignColumns: [albums.id],
    }).onDelete("restrict"),
    // Not unique per album: an album may have several journals (D1.1).
    uniqueIndex("album_journals_one_featured_idx")
      .on(t.albumId)
      .where(sql`is_featured`),
    // Target of the track-reflection key, which keeps reflections on the
    // journal's own album.
    unique("album_journals_entry_album_unique").on(t.entryId, t.albumId),
    check("album_journals_kind_check", sql`kind = 'album_journal'`),
    ratingCheck("album_journals"),
    index("album_journals_album_id_idx").on(t.albumId),
  ],
);

export const artistJournals = pgTable(
  "artist_journals",
  {
    entryId: uuid("entry_id").primaryKey(),
    kind: text("kind", { enum: ["artist_journal"] })
      .notNull()
      .default("artist_journal"),
    artistId: uuid("artist_id").notNull(),
    isFeatured: boolean("is_featured").notNull().default(false),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    foreignKey({
      name: "artist_journals_entry_fk",
      columns: [t.entryId, t.kind],
      foreignColumns: [entries.id, entries.kind],
    }).onDelete("cascade"),
    foreignKey({
      name: "artist_journals_artist_fk",
      columns: [t.artistId],
      foreignColumns: [artists.id],
    }).onDelete("restrict"),
    uniqueIndex("artist_journals_one_featured_idx")
      .on(t.artistId)
      .where(sql`is_featured`),
    check("artist_journals_kind_check", sql`kind = 'artist_journal'`),
    index("artist_journals_artist_id_idx").on(t.artistId),
  ],
);

export const memories = pgTable(
  "memories",
  {
    entryId: uuid("entry_id").primaryKey(),
    kind: text("kind", { enum: ["memory"] })
      .notNull()
      .default("memory"),
    // Free text: "a date, a season, a year".
    rememberedWhen: text("remembered_when"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    foreignKey({
      name: "memories_entry_fk",
      columns: [t.entryId, t.kind],
      foreignColumns: [entries.id, entries.kind],
    }).onDelete("cascade"),
    check("memories_kind_check", sql`kind = 'memory'`),
  ],
);

// A reflection on one recording of the journal's album. It refers to the
// album and the recording, never to a position in an edition (D2.3).
export const trackReflections = pgTable(
  "track_reflections",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    albumJournalId: uuid("album_journal_id").notNull(),
    albumId: uuid("album_id").notNull(),
    trackId: uuid("track_id").notNull(),
    // Explicit per-track publication permission (D5.2). Off by default.
    isPublished: boolean("is_published").notNull().default(false),
    // Writing progress only; it never affects visibility (D5.1, INV-2).
    isStillWriting: boolean("is_still_writing").notNull().default(false),
    isFavourite: boolean("is_favourite").notNull().default(false),
    ratingHalfSteps: smallint("rating_half_steps"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    foreignKey({
      name: "track_reflections_journal_fk",
      columns: [t.albumJournalId, t.albumId],
      foreignColumns: [albumJournals.entryId, albumJournals.albumId],
    }).onDelete("cascade"),
    foreignKey({
      name: "track_reflections_album_track_fk",
      columns: [t.albumId, t.trackId],
      foreignColumns: [albumTracks.albumId, albumTracks.trackId],
    }).onDelete("restrict"),
    unique("track_reflections_journal_track_unique").on(
      t.albumJournalId,
      t.trackId,
    ),
    ratingCheck("track_reflections"),
    index("track_reflections_album_track_idx").on(t.albumId, t.trackId),
  ],
);

// The text of a track reflection in one language.
export const trackReflectionTexts = pgTable(
  "track_reflection_texts",
  {
    trackReflectionId: uuid("track_reflection_id").notNull(),
    locale: text("locale", { enum: locales }).notNull(),
    ...richText(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    primaryKey({
      name: "track_reflection_texts_pkey",
      columns: [t.trackReflectionId, t.locale],
    }),
    foreignKey({
      name: "track_reflection_texts_reflection_fk",
      columns: [t.trackReflectionId],
      foreignColumns: [trackReflections.id],
    }).onDelete("cascade"),
    localeCheck("track_reflection_texts"),
    ...richTextChecks("track_reflection_texts"),
  ],
);

// The ordered songs and albums a memory belongs to. Removing a link deletes
// only the link, never the music (Product, rule 6).
export const memoryMusic = pgTable(
  "memory_music",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    memoryId: uuid("memory_id").notNull(),
    // UNIQUE (memory_id, position) DEFERRABLE INITIALLY DEFERRED is added by
    // a custom migration, so the list can be reordered in one transaction.
    position: smallint("position").notNull(),
    trackId: uuid("track_id"),
    albumId: uuid("album_id"),
    createdAt: createdAt(),
  },
  (t) => [
    foreignKey({
      name: "memory_music_memory_fk",
      columns: [t.memoryId],
      foreignColumns: [memories.entryId],
    }).onDelete("cascade"),
    foreignKey({
      name: "memory_music_track_fk",
      columns: [t.trackId],
      foreignColumns: [tracks.id],
    }).onDelete("restrict"),
    foreignKey({
      name: "memory_music_album_fk",
      columns: [t.albumId],
      foreignColumns: [albums.id],
    }).onDelete("restrict"),
    unique("memory_music_track_unique").on(t.memoryId, t.trackId),
    unique("memory_music_album_unique").on(t.memoryId, t.albumId),
    check(
      "memory_music_one_item_check",
      sql`num_nonnulls(track_id, album_id) = 1`,
    ),
    check("memory_music_position_check", sql`position >= 1`),
    index("memory_music_track_id_idx").on(t.trackId),
    index("memory_music_album_id_idx").on(t.albumId),
  ],
);

// Current and previous public slugs. The primary key makes a slug unique per
// entry kind across current and previous slugs, so no two rows can hold the
// same slug (D7.3). Keeping previous-slug rows while their entry exists
// (D7.5), and giving every entry a current slug (D7.1), are rules of the
// Publication commands: rows are only ever added or marked non-current, never
// deleted or re-pointed. Rows cascade with their entry, so a permanent
// deletion releases them (ADR 0003).
export const entrySlugs = pgTable(
  "entry_slugs",
  {
    kind: text("kind", { enum: entryKinds }).notNull(),
    slug: text("slug").notNull(),
    entryId: uuid("entry_id").notNull(),
    isCurrent: boolean("is_current").notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    primaryKey({ name: "entry_slugs_pkey", columns: [t.kind, t.slug] }),
    foreignKey({
      name: "entry_slugs_entry_fk",
      columns: [t.entryId, t.kind],
      foreignColumns: [entries.id, entries.kind],
    }).onDelete("cascade"),
    uniqueIndex("entry_slugs_one_current_idx")
      .on(t.entryId)
      .where(sql`is_current`),
    // The normalized form of D7.2: lowercase ASCII letters and digits in
    // hyphen-separated runs, at most 80 characters.
    check(
      "entry_slugs_slug_format_check",
      sql`slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(slug) <= 80`,
    ),
    index("entry_slugs_entry_id_idx").on(t.entryId),
  ],
);
